// GENERATED by scripts/sync-gateway.mjs from gateway/src/. Do not edit.
// AGMARKNET prices through data.gov.in ("Current Daily Price of Various Commodities from Various Markets (Mandi)").
// This is a REAL adapter. It only stores what the API returns. It never fills gaps and never invents a price.

import { and, desc, eq, gte, lte } from 'drizzle-orm';
import type { Db } from '../db/client.js';
import { priceSeries } from '../db/schema.js';

export const DATAGOVIN_RESOURCE_ID = '9ef84268-d588-465a-a308-a864a43d0070';
export const DATAGOVIN_URL = `https://api.data.gov.in/resource/${DATAGOVIN_RESOURCE_ID}`;

/** Markets of the pilot area (CONTRACT.md Section 4.2 and the task brief) and the commodities we track. */
export const TRACKED_MARKETS = ['Medinipur(West)', 'Ghatal', 'Garbeta', 'Tamluk (Medinipur E)', 'Egra/Contai'] as const;
/**
 * Valuation preference: the Paschim Medinipur markets first, then the nearest reporting Purba Medinipur markets. On 16-10-2026 only the
 * latter reported (DECISIONS D25). Anything but the first entry is shown as "nearest reporting market".
 */
export const MARKET_PREFERENCE = TRACKED_MARKETS;
export const TRACKED_COMMODITIES = ['Potato', 'Brinjal', 'Cauliflower', 'Tomato', 'Paddy(Dhan)', 'Rice'] as const;

export interface DataGovRecord { state: string; district: string; market: string; commodity: string; variety: string; grade?: string; arrival_date: string; min_price: string; max_price: string; modal_price: string }
export interface PriceRow { date: string; market: string; commodity: string; variety: string; minPrice: number; maxPrice: number; modalPrice: number; source: string }

const norm = (s: string) => s.toLowerCase().replace(/[\s()]/g, '');

/** dd/mm/yyyy (data.gov.in) to yyyy-mm-dd. */
export function isoDate(d: string): string | undefined {
  const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(d.trim());
  return m ? `${m[3]}-${m[2]}-${m[1]}` : /^\d{4}-\d{2}-\d{2}$/.test(d.trim()) ? d.trim() : undefined;
}

/** Keeps only rows for the tracked markets and commodities, with numeric prices. Rows that do not parse are dropped, not repaired. */
export function parseRecords(records: DataGovRecord[], sourceLabel: string): PriceRow[] {
  const markets = TRACKED_MARKETS.map(norm), commodities = TRACKED_COMMODITIES.map(norm);
  const out: PriceRow[] = [];
  for (const r of records) {
    const date = isoDate(r.arrival_date ?? '');
    const min = Number(r.min_price), max = Number(r.max_price), modal = Number(r.modal_price);
    if (!date || ![min, max, modal].every((n) => Number.isFinite(n) && n > 0)) continue;
    if (!markets.some((m) => norm(r.market).includes(m)) || !commodities.some((c) => norm(r.commodity).includes(c))) continue;
    out.push({ date, market: r.market.trim(), commodity: r.commodity.trim(), variety: (r.variety ?? '').trim(), minPrice: min, maxPrice: max, modalPrice: modal, source: sourceLabel });
  }
  return out;
}

export class AgmarknetAdapter {
  constructor(private db: Db, private opts: { apiKey?: string; fetchImpl?: typeof fetch }) {}
  get configured() { return !!this.opts.apiKey; }

  /** Fetches today's published prices for West Bengal and stores the tracked rows. Needs DATAGOVIN_API_KEY. */
  async snapshot(): Promise<{ fetched: number; stored: number }> {
    if (!this.opts.apiKey) throw new Error('DATAGOVIN_API_KEY is not set: no price fetch was attempted');
    const f = this.opts.fetchImpl ?? fetch;
    const rows: PriceRow[] = [];
    let offset = 0, total = Infinity, fetched = 0;
    while (offset < total && offset < 20000) {
      const u = new URL(DATAGOVIN_URL);
      u.searchParams.set('api-key', this.opts.apiKey); u.searchParams.set('format', 'json'); u.searchParams.set('limit', '1000'); u.searchParams.set('offset', String(offset));
      u.searchParams.set('filters[state.keyword]', 'West Bengal');
      const res = await f(u, { headers: { accept: 'application/json' } });
      if (!res.ok) throw new Error(`data.gov.in answered HTTP ${res.status}`);
      const body = (await res.json()) as { total?: number; count?: number; records?: DataGovRecord[] };
      const recs = body.records ?? [];
      total = Number(body.total ?? recs.length); fetched += recs.length;
      rows.push(...parseRecords(recs, `data.gov.in resource ${DATAGOVIN_RESOURCE_ID}`));
      if (recs.length === 0) break;
      offset += recs.length;
    }
    return { fetched, stored: await this.store(rows) };
  }

  async store(rows: PriceRow[]): Promise<number> {
    let n = 0;
    for (let i = 0; i < rows.length; i += 500) {
      const chunk = rows.slice(i, i + 500);
      await this.db.insert(priceSeries).values(chunk).onConflictDoNothing();
      n += chunk.length;
    }
    return n;
  }

  /**
   * The valuation price for a commodity: the most preferred market (MARKET_PREFERENCE) that has a row within `maxAgeDays` of `onOrBefore`.
   * Undefined if no tracked market reported recently. There is no fallback value.
   */
  async basisFor(commodity: string, onOrBefore: string, maxAgeDays = 7) {
    const from = new Date(new Date(`${onOrBefore}T00:00:00Z`).getTime() - maxAgeDays * 86400000).toISOString().slice(0, 10);
    const rows = await this.db.select().from(priceSeries).where(and(eq(priceSeries.commodity, commodity), lte(priceSeries.date, onOrBefore), gte(priceSeries.date, from))).orderBy(desc(priceSeries.date));
    for (const m of MARKET_PREFERENCE) { const hit = rows.find((r) => norm(r.market).includes(norm(m))); if (hit) return { ...hit, preferred: m === MARKET_PREFERENCE[0] }; }
    return undefined;
  }

  /** Latest modal price on or before `onOrBefore` for one market and commodity; undefined if the series has nothing (no fallback value). */
  async latestModal(market: string, commodity: string, onOrBefore: string) {
    const rows = await this.db.select().from(priceSeries)
      .where(and(eq(priceSeries.market, market), eq(priceSeries.commodity, commodity), lte(priceSeries.date, onOrBefore))).orderBy(desc(priceSeries.date)).limit(1);
    return rows[0];
  }

  async series(q: { commodity?: string; market?: string; from?: string; to?: string }) {
    const conds = [q.commodity ? eq(priceSeries.commodity, q.commodity) : undefined, q.market ? eq(priceSeries.market, q.market) : undefined, q.from ? gte(priceSeries.date, q.from) : undefined, q.to ? lte(priceSeries.date, q.to) : undefined].filter(Boolean) as ReturnType<typeof eq>[];
    return this.db.select().from(priceSeries).where(conds.length ? and(...conds) : undefined).orderBy(desc(priceSeries.date)).limit(1000);
  }
}
